4 for $x_i \in X_{Maj}$ do  
5 nn $\leftarrow$ nearestNeighbors $(x_i, X)$ ;  
6 $D \gets D \cup$ calculateDS $(x_i, nn)$ ;  
7 end  
8 $\alpha \gets$ normalize(D);  
9 $N \gets$ min(||X_Maj| - ||X_Min|, 0.5||X||)  
